COMPACT = {"faith-sites","climate-change","fashion"}

def row(i, item):
    aid,title,img,alt,paras,links = item
    txt = "".join(p if p.startswith("<h3") else f"<p>{p}</p>" for p in paras)
    xl = ""
    if links:
        xl = '<div class="xlinks">' + "".join(f'<a class="link-arrow" href="{(h if "." in h else "#"+h)}">{t} {ARROW}</a>' for t,h in links) + '</div>'
    arch = " archival archival-hover" if i % 3 == 2 else ""
    cls = "prog" + (" flip" if i % 2 else "") + (" compact" if aid in COMPACT else "")
    return f'<article class="{cls}" id="{aid}" aria-labelledby="{aid}-h"><div class="prog-media"><figure class="frame ratio-43{arch}"><div class="fi">{picture(img, alt, "(max-width:980px) 100vw, 560px")}</div><figcaption><span>Placeholder photo</span><span>No. {i+1:02d}</span></figcaption></figure></div><div class="reveal"><span class="idx">Programme No. {i+1:02d}</span><h2 id="{aid}-h">{title}</h2>{txt}{xl}</div></article>'

def build():
    first = "".join(row(i, p) for i, p in enumerate(P[:7]))
